// ── 유틸 ──
function cleanDrugName(s) {
  // 숫자+단위 제거, 괄호 이후 제거 → 순수 한글 제품명
  let c = (s || "").replace(/_/g, "");
  c = c.replace(/\d+[\w]*/g, "");
  c = c.split(/[(\s,.\/]/)[0].trim();
  return c;
}

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({length: n+1}, (_, i) => i);
  for (let i = 1; i <= m; i++) {
    let prev = dp[0]; dp[0] = i;
    for (let j = 1; j <= n; j++) {
      const temp = dp[j];
      dp[j] = a[i-1] === b[j-1] ? prev : 1 + Math.min(prev, dp[j], dp[j-1]);
      prev = temp;
    }
  }
  return dp[n];
}

// ── 핵심 매칭 전략 ──
// 전제: 처방 약물은 100% DB 내 존재
// 원칙:
function matchDrug(code, rawName) {
  // ★ 최종 매칭 전략 ★
  // 1순위: 코드 완전일치 (병원DB)
  // 2순위: 이름 유사도 + 조제량 가중치 (병원DB) — 코드 자릿수 보정보다 이름 우선
  // 3순위: 코드 자릿수 보정 (병원DB)
  // 4순위: 코드 완전일치 (전체DB)
  // 5순위: 코드 자릿수 보정 + 이름 유사도 (전체DB) — 이름 우선
  // hospitalContext: 전역변수로 OCR에서 인식된 병원명

  const hosp = window._detectedHospital || "";
  const hospList = hosp ? (HOSPITAL_DB[hosp] || []) : [];
  const hospMax = hospList.length ? Math.max(...hospList.map(d => d.amount || 0)) || 1 : 1;

  // 코드 인덱스 (병원)
  const hospCodeIdx = {};
  hospList.forEach(d => { hospCodeIdx[d.code] = d; });

  // 이름 유사도 + 조제량 가중치
  function nameScore(candidates, maxAmt) {
    const query = cleanDrugName(rawName);
    if (!query || query.length < 2) return { hit: null, score: 9999 };
    let best = null, bestScore = 9999;
    for (const d of candidates) {
      const c = cleanDrugName(d.name);
      const dist = (c.includes(query) || query.includes(c)) ? 0 : levenshtein(query, c);
      const norm = (d.amount || 0) / maxAmt;
      const score = dist * (1 - norm * 0.3);
      if (score < bestScore) { bestScore = score; best = d; }
    }
    return { hit: best, score: bestScore };
  }

  // 코드 자릿수 보정
  function codeFixed(codeIdx) {
    if (!code || code.length < 8 || code.length > 11 || code.length === 9) return null;
    for (let i = 0; i < code.length; i++) {
      const c = code.slice(0, i) + code.slice(i + 1);
      if (c.length === 9 && codeIdx[c]) return codeIdx[c];
    }
    return null;
  }

  // ── 1순위: 코드 완전일치 (병원DB) ──
  if (code && hospCodeIdx[code])
    return { ...hospCodeIdx[code], confidence: "high" };

  // ── 2순위+3순위: 이름 유사도 vs 코드 자릿수 보정 (병원DB) ── 이름 우선 ──
  if (hospList.length) {
    const nm = nameScore(hospList, hospMax);
    const cf = codeFixed(hospCodeIdx);

    if (nm.hit && cf) {
      if (nm.hit.name === cf.name)
        return { ...nm.hit, confidence: "high" };
      return { ...nm.hit, confidence: "name" }; // 이름 우선
    }
    if (nm.hit && nm.score <= 2.0)
      return { ...nm.hit, confidence: "name" };
    if (cf)
      return { ...cf, confidence: "high" };
  }

  // ── 4순위: 코드 완전일치 (전체DB) ──
  if (code && CODE_INDEX[code])
    return { ...CODE_INDEX[code][0], confidence: "high" };

  // ── 5순위: 코드 자릿수 보정 + 이름 유사도 (전체DB) — 이름 우선 ──
  const allMax = Math.max(...DRUG_LIST.map(d => d.amount || 0)) || 1;
  const nm2 = nameScore(DRUG_LIST, allMax);
  const allCodeIdx = {};
  CODE_INDEX && Object.entries(CODE_INDEX).forEach(([k, v]) => { allCodeIdx[k] = v[0]; });
  const cf2 = codeFixed(allCodeIdx);

  if (nm2.hit && cf2) {
    if (nm2.hit.name === cf2.name)
      return { ...nm2.hit, confidence: "high" };
    return { ...nm2.hit, confidence: "name" }; // 이름 우선
  }
  if (cf2) return { ...cf2, confidence: "high" };
  if (nm2.hit) return { ...nm2.hit, confidence: "fuzzy" };

  return DRUG_LIST.length ? { ...DRUG_LIST[0], confidence: "fuzzy" } : null;
}

// ── Claude API ──
async function callClaude(messages, systemPrompt) {
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": process.env.REACT_APP_ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
      "anthropic-dangerous-direct-browser-access": "true",
    },
    body: JSON.stringify({ model: CLAUDE_MODEL, max_tokens: 4096, system: systemPrompt, messages }),
  });
  const d = await res.json();
  return d.content?.[0]?.text || "";
}

function toBase64(file) {
  return new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res({ data: reader.result.split(",")[1], mimeType: file.type });
    reader.onerror = rej;
    reader.readAsDataURL(file);
  });
}

