// ── 처방전 탭 ──
function PrescriptionTab({ onSave }) {
  const [phase, setPhase] = useState("idle");
  const [step, setStep] = useState(0);
  const [preview, setPreview] = useState(null);
  const [b64, setB64] = useState(null);
  const [mimeType, setMimeType] = useState("image/jpeg");
  const [result, setResult] = useState(null);
  const [detectedHospital, setDetectedHospital] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);
  const fileRef = useRef();

  const handleFile = useCallback(async (file) => {
    if (!file) return;
    const { data, mimeType: detected } = await toBase64(file);
    setB64(data); setMimeType(detected);
    setPreview(URL.createObjectURL(file));
    setPhase("idle"); setStep(0); setResult(null); setDetectedHospital(null);
  }, []);

  const analyze = async () => {
    if (!b64) return;
    setResult(null); setPhase("analyzing");
    try {
      // ── STEP 1: 병원명만 추출 ──────────────────────────────────
      setStep(1);
      const step1Text = await callClaude([{
        role: "user",
        content: [
          { type: "image", source: { type: "base64", media_type: mimeType, data: b64 } },
          { type: "text", text: `처방전 상단의 의원/병원명을 추출하라.
JSON만 출력: {"hospitalName":"병원명전체"}` }
        ]
      }], "처방전 병원명 추출 전문가. JSON만 출력.");

      const step1Data = JSON.parse(step1Text.replace(/```json|```/g,"").trim());
      const rawHospName = step1Data?.hospitalName || "";

      // 병원명 → DB 키 매칭
      let matchedHosp = "";
      for (const [dbKey, aliases] of Object.entries(HOSPITAL_ALIASES)) {
        if (aliases.some(a => rawHospName.includes(a))) {
          matchedHosp = dbKey;
          break;
        }
      }

      // 미등록 병원 처리
      if (!matchedHosp) {
        setPhase("idle"); setStep(0);
        alert(`"${rawHospName}"은 등록되지 않은 병원입니다.\n병원명이 잘 보이도록 다시 촬영해주세요.`);
        return;
      }

      setDetectedHospital(matchedHosp);
      window._detectedHospital = matchedHosp;

      // ── STEP 2: 이미지 + 병원 약목록 → Claude 직접 매칭 ─────────
      setStep(2);
      const drugList = HOSPITAL_DRUG_TEXT[matchedHosp] || "";

      const step2Text = await callClaude([{
        role: "user",
        content: [
          { type: "image", source: { type: "base64", media_type: mimeType, data: b64 } },
          { type: "text", text: `처방전 이미지와 아래 약목록을 함께 보고 처방 약을 정확히 매칭하라.

[약목록] (형식: 청구코드 약품명 [약효군])
${drugList}

[규칙]
1. 처방전의 각 약품을 위 목록에서 찾아라
2. 코드와 이름을 함께 보고 판단하라 (코드 우선, 이름으로 보정)
3. 1회량(dose), 1일횟수(frequency), 투약일수(days) 추출
4. 목록에 없는 약은 rawName 그대로 기재

JSON만 출력:
{"items":[{"code":"9자리코드","matchedName":"약목록의정확한약품명","category":"약효군","dose":"","frequency":"","days":""}]}` }
        ]
      }], "한국 처방전 약품 매칭 전문가. JSON만 출력.");

      const step2Data = JSON.parse(step2Text.replace(/```json|```/g,"").trim());
      if (!step2Data?.items?.length) throw new Error("약물 정보를 찾을 수 없습니다.");

      // ── STEP 3: 복약지도 생성 ──────────────────────────────────
      setStep(3);
      const finalText = await callClaude([{
        role: "user",
        content: [{ type: "text", text: `한국 전문 약사 AI. 아래 데이터로 복약지도를 생성하라.

[핵심 원칙]
- matchedName은 병원 실제 조제자료에서 검증된 정확한 약품명이다. 절대 변경 금지.
- name 필드에는 반드시 matchedName을 그대로 사용할 것.
- category 필드: 제공된 category 값을 그대로 사용.

[effect] 성분명 기반 정확한 효능을 환자 눈높이 1~2문장으로 작성.
[복약지도] 복용법·식사관계·보관법만. 주의사항·부작용 절대 금지.

처방 데이터:
${JSON.stringify(step2Data.items, null, 2)}

JSON만 출력:
{"drugs":[{"name":"matchedName그대로","dose":"용량","usage":"용법","category":"약효군","effect":"효능"}],"guidance":"복약지도(300자 이내)"}` }]
      }], "한국 전문 약사 AI. JSON만 출력.");

      const finalData = JSON.parse(finalText.replace(/```json|```/g,"").trim());
      setResult(finalData);
      setPhase("done");
    } catch(e) {
      setPhase("idle"); setStep(0);
      alert(`분석 오류: ${e.message || "다시 시도해주세요."}`);
    }
  };;

  const save = () => {
    if (!result) return;
    onSave({ date: new Date().toLocaleDateString("ko-KR"), drugs: result.drugs.map(d => d.name), detail: result, image: preview });
    alert("저장되었습니다!");
  };

  return (
    <div className="p-4 space-y-4">
      <ImageModal src={modalOpen ? preview : null} onClose={() => setModalOpen(false)} />
      <h2 className="text-lg font-bold text-gray-800">처방전 복약지도</h2>
      <div className="bg-white rounded-2xl shadow overflow-hidden">
        {preview ? (
          <div className="relative">
            <img src={preview} alt="처방전" className="w-full object-contain max-h-48 cursor-zoom-in" onClick={() => setModalOpen(true)} />
            <div className="absolute bottom-2 right-2 bg-black bg-opacity-40 text-white text-xs px-2 py-1 rounded-full">🔍 탭하여 확대</div>
            <button onClick={() => { setPreview(null); setB64(null); setResult(null); setPhase("idle"); setStep(0); setDetectedHospital(null); }}
              className="absolute top-2 right-2 bg-black bg-opacity-50 text-white rounded-full w-7 h-7 flex items-center justify-center text-sm">✕</button>
          </div>
        ) : (
          <button onClick={() => fileRef.current.click()} className="w-full h-40 flex flex-col items-center justify-center text-gray-400 border-2 border-dashed border-gray-200 rounded-2xl">
            <span className="text-4xl">📸</span>
            <span className="mt-2 text-sm">처방전 사진 촬영 / 선택</span>
          </button>
        )}
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp,image/gif"
          className="hidden" onChange={e => handleFile(e.target.files[0])} />
      </div>

      {preview && phase === "idle" && (
        <button onClick={analyze} className="w-full py-3 bg-blue-600 text-white font-bold rounded-2xl shadow">💊 복약지도 받기</button>
      )}
      {phase === "analyzing" && <AnalysisProgress step={step} />}

      {result && phase === "done" && (
        <div className="space-y-4">
          {detectedHospital && (
            <div className="rounded-xl px-4 py-2 bg-blue-50 border border-blue-100">
              <p className="text-xs font-semibold text-blue-700">🏥 {detectedHospital} · {result.drugs.length}종</p>
            </div>
          )}
          <div className="bg-white rounded-2xl shadow overflow-hidden">
            <div className="px-4 pt-4 pb-2"><p className="text-base font-bold text-gray-800">💊 처방 약물 ({result.drugs.length}종)</p></div>
            {result.drugs?.map((d, i) => <DrugCard key={i} d={d} />)}
          </div>
          <div className="bg-green-50 rounded-2xl p-4 border border-green-200">
            <p className="text-base font-bold text-green-700 mb-3">📋 복약지도</p>
            <p className="text-sm text-gray-800 leading-loose">{result.guidance}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => { setResult(null); setPhase("idle"); setStep(0); setDetectedHospital(null); }}
              className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-2xl">🔄 다시 분석</button>
            <button onClick={save} className="flex-1 py-3 bg-green-600 text-white font-bold rounded-2xl shadow">💾 저장하기</button>
          </div>
        </div>
      )}
    </div>
  );
}

